+        boolean hasEmail = !emailValue.isBlank();
+        boolean hasPhone = !phone.getValue().isBlank();
+        if (hasEmail && new EmailValidator(INVALID_EMAIL)
+                .apply(emailValue, new ValueContext(email)).isError()) {
+            email.setInvalid(true);
+            email.setErrorMessage(INVALID_EMAIL);
+            valid = false;
+        } else if (!hasEmail && !hasPhone) {
+            email.setInvalid(true);
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            valid = false;
+        } else {
+            email.setInvalid(false);
+            email.setErrorMessage(null);
+        }
+
+        boolean messagePresent = !message.getValue().isBlank();
+        boolean messageWithinLimit = message.getValue().length() <= 500;
+        if (!messagePresent) {
+            message.setInvalid(true);
+            message.setErrorMessage("Message is required");
+            valid = false;
+        } else if (!messageWithinLimit) {
+            message.setInvalid(true);
+            message.setErrorMessage("Message must be at most 500 characters");
+            valid = false;
+        } else {
+            message.setInvalid(false);
+            message.setErrorMessage(null);
+        }
+
+        return valid;
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasDraft()) {
+            return;
+        }
+
+        ContinueNavigationAction navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        Button keepEditing = new Button("Keep editing", click -> {
+            navigation.cancel();
+            dialog.close();
+        });
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.add(keepEditing, discard);
+        dialog.open();
+    }
+
+    private boolean hasDraft() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+}
